class Listener:
    """protocol Listener: message classes by method number, and its Client and Handler."""

    REQUESTS = {
        1: Started,
        2: Output,
        3: Finished,
    }

    RESPONSES = {}

    class Client(system.Client):
        """protocol Listener: client, for a handle to a service."""

        def started(self, number: int = 0) -> None:
            """Listener.Started, one-way."""
            self.send(Started(number=number))

        def output(self, stream: str = '', text: str = '') -> None:
            """Listener.Output, one-way."""
            self.send(Output(stream=stream, text=text))

        def finished(self, result: Result | None = None) -> None:
            """Listener.Finished, one-way."""
            self.send(Finished(result=result))

    class Handler(system.Handler):
        """protocol Listener: base class for a service's handler."""

        METHODS = {
            1: (Started, "started"),
            2: (Output, "output"),
            3: (Finished, "finished"),
        }

        def started(self, request: Started, source: int) -> None:
            """Handle Listener.Started, one-way."""
            raise NotImplementedError

        def output(self, request: Output, source: int) -> None:
            """Handle Listener.Output, one-way."""
            raise NotImplementedError

        def finished(self, request: Finished, source: int) -> None:
            """Handle Listener.Finished, one-way."""
            raise NotImplementedError


class Starter:
    """protocol Starter: message classes by method number, and its Client and Handler."""

    REQUESTS = {
        1: Ready,
    }

    RESPONSES = {}

    class Client(system.Client):
        """protocol Starter: client, for a handle to a service."""

        def ready(self, evaluator: int | None = None) -> None:
            """Starter.Ready, one-way."""
            self.send(Ready(evaluator=evaluator))

    class Handler(system.Handler):
        """protocol Starter: base class for a service's handler."""

        METHODS = {
            1: (Ready, "ready"),
        }

        def ready(self, request: Ready, source: int) -> None:
            """Handle Starter.Ready, one-way."""
            raise NotImplementedError
